import { Component, inject, Input, OnInit, OnDestroy, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { DocumentoTramite } from "../../../shared/documento-tramite/documento-tramite";
import { TramiteTipo } from '../../../../../models/tramite';
import { TramiteService } from '../../../../../controllers/tramite.service';
import { GenerarSolicitudEstimulos } from '../../../../../services/documentos/solicitud-estimulos/documento-solicitud-estimulos';
import { STEP_SAVE_SLUG_OPTIONS, StepSaveService } from '../../../../../controllers/step-save.service';
import { StepSave } from '../../../../../models/step-save';
import { PuntosAnexoService, ResultadoPuntos } from '../../../../../controllers/puntos-anexo.service';
import { firstValueFrom } from 'rxjs';

@Component({
  selector: 'app-paso-10-solicitud-estimulo',
  imports: [CommonModule, FormsModule, DocumentoTramite],
  templateUrl: './paso-10-solicitud-estimulo.html',
  styleUrl: './paso-10-solicitud-estimulo.css'
})
export class Paso10SolicitudEstimulo implements OnInit, OnDestroy {
  @Input() isCompleted = false;
  stepSave?: StepSave;
  resultadoPuntos = signal<ResultadoPuntos | null>(null);
  tramiteTipo: TramiteTipo = 'inversion_privada';
  fecha_inicio_estimulo = '';
  isSaving = false;

  private tramiteService = inject(TramiteService);
  private generarSolicitudEstimulos = inject(GenerarSolicitudEstimulos);
  private stepSaveService = inject(StepSaveService);
  private puntosAnexoService = inject(PuntosAnexoService);

  async ngOnInit() {
    const tramite = await this.tramiteService.getCurrentTramite();
    if (!tramite) {
      return;
    }
    this.tramiteTipo = tramite.tipo ?? 'inversion_privada';
    
    if (tramite.fecha_inicio_estimulo) {
      this.fecha_inicio_estimulo = tramite.fecha_inicio_estimulo.split('T')[0].split(' ')[0];
    } else {
      this.fecha_inicio_estimulo = '';
    }

    this.stepSave = await firstValueFrom(
      this.stepSaveService.getStep(tramite.id, STEP_SAVE_SLUG_OPTIONS.STATUS_TRAMITE)
    );
    const resultado = await this.puntosAnexoService.actualizarPuntos(tramite);
    this.resultadoPuntos.set(resultado);
  }

  async ngOnDestroy() {
    await this.guardarDatos();
  }

  async guardarDatos() {
    const tramite = await this.tramiteService.getCurrentTramite();
    if (tramite) {
      if (
        this.fecha_inicio_estimulo !== (tramite.fecha_inicio_estimulo?.split('T')[0].split(' ')[0] || '')
      ) {
        await this.tramiteService.fastUpdate(tramite, {
          fecha_inicio_estimulo: this.fecha_inicio_estimulo
        });
      }
    }
  }

  async generarSolicitud() {
    const tramite = await this.tramiteService.getCurrentTramite();
    if (tramite) {
      if (!this.pasosRequeridosCompletados) {
        return;
      }
      this.isSaving = true;
      try {
        await this.guardarDatos();
        await this.generarSolicitudEstimulos.generar(tramite);
      } finally {
        this.isSaving = false;
      }
    }
  }

  get pasosRequeridosCompletados(): boolean {
    const completed = this.stepSave?.completed_steps || [];
    if (this.tramiteTipo === 'tratamiento_agua') {
      return completed.includes(5) && completed.includes(6);
    }
    return completed.includes(7) && completed.includes(8);
  }

  get puedeGenerarPDF(): boolean {
    return this.pasosRequeridosCompletados && !this.isCompleted;
  }
}
