import { Component, computed, inject, OnInit, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Tramite } from '../../../../models/tramite';
import { TramiteService } from '../../../../controllers/tramite.service';
import { TramiteDocumento } from '../../../../models/tramite-documento';
import { TramiteDocumentoService } from '../../../../controllers/tramite-documento.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-tramite-anexo-fuera-cabecera-municipal',
  imports: [CommonModule],
  templateUrl: './tramite-anexo-fuera-cabecera-municipal.html',
  styleUrl: './tramite-anexo-fuera-cabecera-municipal.css',
})
export class TramiteAnexoFueraCabeceraMunicipal implements OnInit {
  tramite = signal<Tramite | undefined>(undefined);
  documentoCabecera = signal<TramiteDocumento | undefined>(undefined);
  loading = signal(false);

  private tramiteService = inject(TramiteService);
  private tramiteDocumentoService = inject(TramiteDocumentoService);
  private router = inject(Router);

  esFueraCabecera = computed(() => 
    this.tramite()?.proyecto_inversion?.fuera_cabecera_municipal ?? false
  );

  noAplica = computed(() => !this.esFueraCabecera());
  tieneDocumento = computed(() => !!this.documentoCabecera());

  async ngOnInit(): Promise<void> {
    this.loading.set(true);
    this.tramite.set(await this.tramiteService.getCurrentTramite(['proyectoInversion']));
    
    if (this.esFueraCabecera()) {
      const docs = await this.tramiteDocumentoService.all({
        conditionals: { 
          seccion: 'proyecto-inversion-cabecera', 
          tramite_id: this.tramite()?.id,
          deleted_at: null
        }
      });
      this.documentoCabecera.set(docs[0]);
    }
    this.loading.set(false);
  }

  irAEditar(): void {
    this.router.navigate(['/main/externos/mi-empresa']);
  }
}
