import { Component, Input, computed, OnChanges, OnInit, inject, signal, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { StepConfig } from './step.interface';
import { Tramite, TramiteTipo } from '../../../models/tramite';
import { Paso1EscritoLibre } from './steps/paso-1-escrito-libre/paso-1-escrito-libre';
import { Paso3PlanNegocios } from './steps/paso-3-plan-negocios/paso-3-plan-negocios';
import { Paso4ActaConstitutiva } from './steps/paso-4-acta-constitutiva/paso-4-acta-constitutiva';
import { Paso5IdRepresentante } from './steps/paso-5-id-representante/paso-5-id-representante';
import { Paso6Cif } from './steps/paso-6-cif/paso-6-cif';
import { Paso7ComprobanteImpuestos } from './steps/paso-7-comprobante-impuestos/paso-7-comprobante-impuestos';
import { Paso8Anexo1Compromisos } from './steps/paso-8-anexo1-compromisos/paso-8-anexo1-compromisos';
import { Paso9Anexos } from './steps/paso-9-anexos/paso-9-anexos';
import { Paso10SolicitudEstimulo } from './steps/paso-10-solicitud-estimulo/paso-10-solicitud-estimulo';
import { Paso11ComprobantePago } from './steps/paso-11-comprobante-pago/paso-11-comprobante-pago';
import { Paso12Csf } from './steps/paso-12-csf/paso-12-csf';
import { TramiteService } from '../../../controllers/tramite.service';
import { Paso2CedulaSei } from "./steps/paso-2-cedula-sei/paso-2-cedula-sei";
import { STEP_SAVE_SLUG_OPTIONS, StepSaveService } from '../../../controllers/step-save.service';
import { DialogData, VanillaDialogService } from '../../../services/vanilla-dialog/vanilla-dialog.service';
import { TramiteComentariosComponent } from '../../tramites/tramites-detalles/tramite-comentarios.component/tramite-comentarios.component';
import { PasoComentariosAdicionales } from "./steps/paso-comentarios-adicionales/paso-comentarios-adicionales";
import { Subscription } from 'rxjs';

const ALL_STEPS: StepConfig[] = [
  { id: 1, title: 'Escrito Libre', isConditional: true, component: Paso1EscritoLibre, isCompleted: false, isOptional: false },
  { id: 2, title: 'Cédula de la SEI', isConditional: true, component: Paso2CedulaSei, isCompleted: false, isOptional: false, autoNext: true },
  { id: 3, title: 'Plan de Negocios o Proyecto de Inversión', isConditional: true, component: Paso3PlanNegocios, isCompleted: false, isOptional: false, autoNext: true },
  { id: 4, title: 'Acta Constitutiva, Poder del Representante Legal', isConditional: false, component: Paso4ActaConstitutiva, isCompleted: false, isOptional: false, autoNext: true },
  { id: 5, title: 'Identificación del Representante Legal', isConditional: false, component: Paso5IdRepresentante, isCompleted: false, isOptional: false, autoNext: true },
  { id: 6, title: 'Cédula de Identificación Fiscal', isConditional: false, component: Paso6Cif, isCompleted: false, isOptional: false, autoNext: true },
  { id: 7, title: 'Comprobante del Último Pago de Impuestos', isConditional: false, component: Paso7ComprobanteImpuestos, isCompleted: false, isOptional: false, autoNext: true },
  { id: 8, title: 'Anexo 1 Formato de Compromisos', isConditional: false, component: Paso8Anexo1Compromisos, isCompleted: false, isOptional: false },
  { id: 9, title: 'Anexos', isConditional: false, component: Paso9Anexos, isCompleted: false, isOptional: false },
  { id: 10, title: 'Comentarios Adicionales', isConditional: false, component: PasoComentariosAdicionales, isCompleted: false, isOptional: false },
  { id: 11, title: 'Solicitud de Estímulo Fiscal', isConditional: false, component: Paso10SolicitudEstimulo, isCompleted: false, isOptional: false, autoNext: true },
  { id: 12, title: 'Comprobante de Pago de Impuestos', isConditional: false, component: Paso11ComprobantePago, isCompleted: false, isOptional: false, autoNext: true },
  { id: 13, title: 'CSF', isConditional: false, component: Paso12Csf, isCompleted: false, isOptional: false, autoNext: true }
];

@Component({
  selector: 'app-status-tramite',
  imports: [
    CommonModule,
    Paso1EscritoLibre,
    Paso3PlanNegocios,
    Paso4ActaConstitutiva,
    Paso5IdRepresentante,
    Paso6Cif,
    Paso7ComprobanteImpuestos,
    Paso8Anexo1Compromisos,
    Paso9Anexos,
    Paso10SolicitudEstimulo,
    Paso11ComprobantePago,
    Paso12Csf,
    Paso2CedulaSei,    
    TramiteComentariosComponent,
    PasoComentariosAdicionales
],
  templateUrl: './status-tramite.html',
  styleUrl: './status-tramite.css'
})
export class StatusTramite implements OnChanges, OnInit, OnDestroy {
  @Input() tramiteTipo: TramiteTipo = 'inversion_privada';
  @Input() tramite: Tramite | null = null;

  private tramiteService = inject(TramiteService);
  private stepSaveService = inject(StepSaveService);
  private dialogService = inject(VanillaDialogService);
  private uploadSub?: Subscription;

  alert: { type: 'success' | 'danger'; message: string } | null = null;

  // Signals for state management
  currentStep = signal(1);
  tramiteTipoSignal = signal<TramiteTipo>('inversion_privada');
  completedStepIds = signal<number[]>([]);

  visibleSteps = computed(() => {
    const type = this.tramiteTipoSignal();
    const completedIds = this.completedStepIds();

    return ALL_STEPS.filter(step => {
      if (step.isConditional) {
        return type === 'inversion_privada' || step.id === 1;
      }
      return true;
    }).map(step => {
      const isCompleted = completedIds.includes(step.id);
      let title = step.title;
      if (step.id === 11 && type === 'tratamiento_agua') {
        title = 'Comprobante del Último Pago Efectuado por Concepto de Suministro de Agua';
      }
      return { ...step, isCompleted, title };
    });
  });

  totalSteps = computed(() => this.visibleSteps().length);

  get currentStepConfig(): StepConfig | undefined {
    return this.visibleSteps()[this.currentStep() - 1];
  }

  get progressPercentage(): number {
    const visible = this.visibleSteps();
    const completedCount = visible.filter(s => s.isCompleted).length;
    return (completedCount / visible.length) * 100;
  }

  get completedSteps(): number {
    return this.visibleSteps().filter(s => s.isCompleted).length;
  }

  get isCurrentStepCompleted(): boolean {
    return this.currentStepConfig?.isCompleted || false;
  }

  get completarButtonText(): string {
    return this.isCurrentStepCompleted
        ? 'Modificar'
        : 'Guardar';
  }

  get completarButtonIcon(): string {
    return this.isCurrentStepCompleted
        ? 'bi-pencil'
        : 'bi-save';
  }

  get completarButtonClass(): string {
    return this.isCurrentStepCompleted
        ? 'btn btn-warning'
        : 'btn btn-primary';
  }

  async ngOnInit(){
    this.tramite = await this.tramiteService.getCurrentTramite(['proyectoInversion', 'empresa'])??null;
    this.tramiteTipo = this.tramite?.tipo ?? 'inversion_privada';
    this.tramiteTipoSignal.set(this.tramiteTipo);
    
    if (this.tramite) {
      this.stepSaveService.getStep(this.tramite.id, STEP_SAVE_SLUG_OPTIONS.STATUS_TRAMITE).subscribe({
        next: (savedStep) => {
          if (savedStep) {
            this.currentStep.set(savedStep.step || 1);
            if (savedStep.completed_steps) {
              this.completedStepIds.set(savedStep.completed_steps);
            }
          }
        },
        error: () => {
          this.currentStep.set(1);
        }
      });
    } else {
      this.currentStep.set(1);
    }

    this.uploadSub = this.stepSaveService.documentUploaded$.subscribe(() => {
      this.handleAutoNext();
    });
  }

  ngOnDestroy() {
    this.uploadSub?.unsubscribe();
  }

  private async handleAutoNext() {
    const config = this.currentStepConfig;
    if (config?.autoNext && !config.isCompleted) {
      await this.markStepComplete(this.currentStep());
    }
  }

  ngOnChanges(): void {
    this.tramiteTipoSignal.set(this.tramiteTipo);
    this.currentStep.set(1);
  }

  goToStep(index: number): void {
    if (index >= 1 && index <= this.totalSteps()) {
      this.currentStep.set(index);
      this.saveCurrentStep();
    }
  }

  nextStep(): void {
    if (this.currentStep() < this.totalSteps()) {
      this.currentStep.update(s => s + 1);
      this.saveCurrentStep();
    }
  }

  previousStep(): void {
    if (this.currentStep() > 1) {
      this.currentStep.update(s => s - 1);
      this.saveCurrentStep();
    }
  }

  saveCurrentStep(): void {
    if (this.tramite) {
      const completed_steps = this.completedStepIds();
      this.stepSaveService.saveStep({
        tramite_id: this.tramite.id,
        anexo_slug: STEP_SAVE_SLUG_OPTIONS.STATUS_TRAMITE,
        step: this.currentStep(),
        completed_steps: completed_steps
      }).subscribe();
    }
  }

  async markStepComplete(stepIndex: number): Promise<void> {
    const steps = this.visibleSteps();
    const step = steps[stepIndex - 1];
    if (step) {
      const currentCompleted = this.completedStepIds();
      const isNowCompleted = !currentCompleted.includes(step.id);
      
      if (isNowCompleted) {
        this.completedStepIds.set([...currentCompleted, step.id]);
      } else {
        this.completedStepIds.set(currentCompleted.filter(id => id !== step.id));
      }

      this.saveCurrentStep();
      await this.stepSaveService.requestSave();

      // Si se marcó como completado, avanzar automáticamente al siguiente paso
      if (isNowCompleted) {
        this.nextStep();
      }
    }
  }

  isStepAccessible(stepIndex: number): boolean {
    if (stepIndex === 1) return true;
    const previousStep = this.visibleSteps()[stepIndex - 2];
    return previousStep?.isCompleted || false;
  }

  get allStepsCompleted(): boolean {
    return this.visibleSteps().every(s => s.isCompleted);
  }
  get puedeEditar(): boolean {
    return this.tramite?.status === 'INICIADA' || !this.tramite?.status;
  }

  private showAlert(type: 'success' | 'danger', message: string): void {
    this.alert = { type, message };
    
    // Cerrar automáticamente después de 5 segundos
    setTimeout(() => {
      this.alert = null;
    }, 5000);
  }

  async confirmarEnvio(): Promise<void> {
    if (!this.allStepsCompleted) return;

    const dialogData: DialogData = {
      title: '¿Estás seguro?',
      body: '¿Está seguro de que deseas enviar el trámite?',
      size: 'md',
      respYes: 'Sí, Enviar',
      respNo: 'Cancelar',
      tipo: 'warning'
    };

    this.dialogService.show(dialogData).subscribe({
      next: (closedData) => {
        if (closedData?.closedByAgree) {
          this.enviarTramite();
        }
      }
    });
  }

   async enviarTramite(): Promise<void> {
    if (this.tramite && this.allStepsCompleted) {
      try {
        await this.tramiteService.marcarComoRecibida(this.tramite.id);
        this.tramite.status = 'RECIBIDA';
        this.showAlert('success', 'Trámite enviado exitosamente');
      } catch (error) {
        console.error('Error:', error);
        this.showAlert('danger', 'Error al enviar el trámite. Intenta de nuevo.');
      }
    }
  }
}
