import { Component, inject, OnInit, signal, computed, effect } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup } from '@angular/forms';
import { debounceTime, distinctUntilChanged } from 'rxjs';
import { Tramite } from '../../../../../models/tramite';
import { TramiteService } from '../../../../../controllers/tramite.service';
import { LocalStorageService } from '../../../../../services/localStorage/local-storage.service';

@Component({
  selector: 'app-paso-comentarios-adicionales',
  standalone: true,
  imports: [FormsModule, CommonModule, ReactiveFormsModule],
  templateUrl: './paso-comentarios-adicionales.html',
  styleUrl: './paso-comentarios-adicionales.css',
  host: {
    '[class.has-changes]': 'hasChanges()'
  }
})
export class PasoComentariosAdicionales implements OnInit {
  tramite ?: Tramite

  private tramiteService = inject(TramiteService);
  private localStorageService = inject(LocalStorageService);
  private fb = inject(FormBuilder);

  comentarioForm: FormGroup;
  usuarioId = this.localStorageService.getUser()?.user.id;

  loading = signal(false);
  saving = signal(false);
  hasChanges = signal(false);
  saveMessage = signal('');
  lastSaved = signal<Date | null>(null);

  readonly AUTOSAVE_DELAY = 3000;

  characterCount = computed(() => {
    const content = this.comentarioForm.get('comentario')?.value || '';
    return content.length;
  });

  wordCount = computed(() => {
    const content = this.comentarioForm.get('comentario')?.value || '';
    return content.trim() ? content.trim().split(/\s+/).length : 0;
  });

  saveStatusText = computed(() => {
    if (this.saving()) return 'Guardando...';
    if (this.lastSaved()) return `Guardado a las ${this.formatTime(this.lastSaved()!)}`;
    if (this.hasChanges()) return 'Tienes cambios sin guardar';
    return '';
  });

  constructor() {
    this.comentarioForm = this.fb.group({
      comentario: ['']
    });

    this.setupAutosave();

    effect(() => {
      const isLoading = this.loading();
      const control = this.comentarioForm.get('comentario');
      if (isLoading) {
        control?.disable();
      } else {
        control?.enable();
      }
    });
  }

  async ngOnInit() {
    await this.loadTramite()
    this.loadExistingComentario();
  }

  async loadTramite(){
    this.tramite = await this.tramiteService.getCurrentTramite();
  }

  private setupAutosave() {
    this.comentarioForm.get('comentario')?.valueChanges.pipe(
      debounceTime(this.AUTOSAVE_DELAY),
      distinctUntilChanged()
    ).subscribe(() => {
      this.autoSave();
    });
  }

  private async loadExistingComentario() {
    if (!this.tramite) {
      return;
    }

    this.loading.set(true);

    if (this.tramite.comentarios_adicionales) {
      this.comentarioForm.patchValue({ comentario: this.tramite.comentarios_adicionales });
      const savedDate = this.tramite.updated_at ?? this.tramite.created_at ?? new Date().toISOString();
      this.lastSaved.set(new Date(savedDate));
    }
    this.loading.set(false);
  }

  async autoSave() {
    if (!this.comentarioForm.valid || this.saving()) return;

    const content = this.comentarioForm.get('comentario')?.value;
    
    // Si no hay cambios reales comparado con lo que ya tiene el tramite, no guardar
    if (content === this.tramite?.comentarios_adicionales) return;

    await this.saveComentario(false);
  }

  async saveManually() {
    if (this.comentarioForm.invalid) {
      this.comentarioForm.markAllAsTouched();
      this.saveMessage.set('Por favor, completa el campo del comentario.');
      setTimeout(() => this.saveMessage.set(''), 5000);
      return;
    }

    await this.saveComentario(true);
  }

  private async saveComentario(showMessage = true) {
    if (!this.tramite?.id) return;

    this.saving.set(true);

    const content = this.comentarioForm.get('comentario')?.value;

    try {
      await this.tramiteService.update(this.tramite.id, { 
        comentarios_adicionales: content 
      }, showMessage);
      
      // Actualizar el objeto local para evitar autosaves innecesarios
      this.tramite.comentarios_adicionales = content;
      this.lastSaved.set(new Date());
      this.hasChanges.set(false);

      if (showMessage) {
        this.saveMessage.set('Comentario guardado correctamente');
        setTimeout(() => this.saveMessage.set(''), 3000);
      }
    } catch (error) {
      console.error('Error al guardar comentario:', error);
      if (showMessage) {
        this.saveMessage.set('Error al guardar el comentario');
        setTimeout(() => this.saveMessage.set(''), 3000);
      }
    } finally {
      this.saving.set(false);
    }
  }

  onContentChange() {
    this.hasChanges.set(true);
  }

  formatTime(date: Date): string {
    return date.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
  }

  get comentario() {
    return this.comentarioForm.get('comentario');
  }
}

