import { Injectable, inject } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { Tramite } from '../models/tramite';
import { TramiteService } from './tramite.service';
import { TramiteAnexoInversionTecnologiaTotal } from '../models/tramite-anexo-inversion-tecnologia-total';

export interface PuntosAnexo {
  consecutivo: number;
  concepto: string;
  puntos: number;
}

export interface ResultadoPuntos {
  detalle: PuntosAnexo[];
  total: number;
}

@Injectable({
  providedIn: 'root'
})
export class PuntosAnexoService {
  private tramiteService = inject(TramiteService);

  private resultadoSubject = new BehaviorSubject<ResultadoPuntos | null>(null);
  public resultado$: Observable<ResultadoPuntos | null> = this.resultadoSubject.asObservable();

  async actualizarPuntos(tramiteData:Tramite|undefined): Promise<ResultadoPuntos | null> {
    if(!tramiteData){
      return null;
    }
    const relations = ['*'];
    const tramite = await this.tramiteService.find(tramiteData.id, relations);
    if (!tramite) {
      this.resultadoSubject.next(null);
      return null;
    }

    const resultado = this.calcularPuntos(tramite);
    this.resultadoSubject.next(resultado);
    return resultado;
  }

  calcularPuntos(tramite: Tramite): ResultadoPuntos {
    const detalle: PuntosAnexo[] = [];

    // 1. Empleos directos
    const puntosDirectos = this.calcularPuntosDirectos(tramite);
    detalle.push({ consecutivo: 1, concepto: 'Empleos directos a generar.', puntos: puntosDirectos });

    // 2. Empleos indirectos
    const puntosIndirectos = this.calcularPuntosIndirectos(tramite);
    detalle.push({ consecutivo: 2, concepto: 'Empleos indirectos a generar.', puntos: puntosIndirectos });

    // 3. Estudiantes
    const puntosEstudiantes = this.calcularPuntosEstudiantes(tramite);
    detalle.push({ consecutivo: 3, concepto: 'Estudiantes a incorporar.', puntos: puntosEstudiantes });

    // 4. Diversidad
    const puntosDiversidad = this.calcularPuntosDiversidad(tramite);
    detalle.push({ consecutivo: 4, concepto: 'Contratación de Personas Adultas Mayores, Madres Solteras, Personas Productivas con Discapacidad y/o Personas egresadas de Albergues, Casa Hogar, o Institución de Asistencia Social para niño, niña o adolescente.', puntos: puntosDiversidad });

    // 5. Nivel Salarial
    const totalEmpleosDirectos = (tramite.anexos_empleos || []).reduce((acc, curr) => acc + (curr.empleos_nuevos || 0), 0);
    const puntosSalarial = this.calcularPuntosSalarial(tramite, totalEmpleosDirectos);
    detalle.push({ consecutivo: 5, concepto: 'Nivel Salarial de nuevos empleos.', puntos: puntosSalarial });

    // 6. Monto Inversión
    const puntosInversion = this.calcularPuntosInversion(tramite);
    detalle.push({ consecutivo: 6, concepto: 'Monto de la inversión.', puntos: puntosInversion });

    // 7. Origen Inversión
    const puntosOrigen = this.calcularPuntosOrigen(tramite);
    detalle.push({ consecutivo: 7, concepto: 'Origen de la inversión.', puntos: puntosOrigen });

    // 8. Inversión Tecnología
    const puntosTecnologia = this.calcularPuntosInversionTecnologia(tramite, tramite.anexo_inversion_tecnologia_total);
    detalle.push({ consecutivo: 8, concepto: 'Inversión en tecnología.', puntos: puntosTecnologia });

    // 9. Proveeduría
    const puntosProveeduria = this.calcularPuntosProveeduria(tramite);
    detalle.push({ consecutivo: 9, concepto: 'Proveeduría.', puntos: puntosProveeduria });

    // 10. Mercados
    const puntosMercados = this.calcularPuntosMercados(tramite);
    detalle.push({ consecutivo: 10, concepto: 'Diversificación de mercados.', puntos: puntosMercados });

    // 11. Prestaciones
    const puntosPrestaciones = this.calcularPuntosPrestaciones(tramite);
    detalle.push({ consecutivo: 11, concepto: 'Prestaciones laborales.', puntos: puntosPrestaciones });

    // 12. Tecnología Limpia
    const puntosLimpia = this.calcularPuntosTecnologiaLimpia(tramite);
    detalle.push({ consecutivo: 12, concepto: 'Empleo de Tecnología Limpia en el Proceso Productivo.', puntos: puntosLimpia });

    // 13. Energía Renovable
    const puntosEnergia = this.calcularPuntosEnergia(tramite);
    detalle.push({ consecutivo: 13, concepto: 'Implementación de Fuentes de Energía Renovables No contaminantes.', puntos: puntosEnergia });

    // 14. Fuera de Cabecera
    const puntosCabecera = this.calcularPuntosCabecera(tramite);
    detalle.push({ consecutivo: 14, concepto: 'Fuera de la Cabecera Municipal (adicional).', puntos: puntosCabecera });

    const total = detalle.reduce((acc, curr) => acc + curr.puntos, 0);

    return { detalle, total };
  }

  private calcularPuntosDirectos(tramite: Tramite): number {
    const totalEmpleos = (tramite.anexos_empleos || []).reduce((acc, curr) => acc + (curr.empleos_nuevos || 0), 0);
    if (totalEmpleos >= 501) return 12;
    if (totalEmpleos >= 251) return 9;
    if (totalEmpleos >= 51) return 6;
    if (totalEmpleos >= 11) return 3;
    if (totalEmpleos >= 1) return 1;
    return 0;
  }

  private calcularPuntosIndirectos(tramite: Tramite): number {
    const total = tramite.anexo_empleo_indirecto?.numero_empleos_generados || 0;
    if (total > 750) return 5;
    if (total >= 501) return 4;
    if (total >= 251) return 3;
    if (total >= 51) return 2;
    if (total >= 11) return 1;
    return 0;
  }

  private calcularPuntosEstudiantes(tramite: Tramite): number {
    const total = tramite.anexo_estudiante?.numero_estudiantes_a_integrar || 0;
    if (total > 25) return 5;
    if (total >= 16) return 4;
    if (total >= 6) return 3;
    if (total >= 1) return 2;
    return 0;
  }

  private calcularPuntosDiversidad(tramite: Tramite): number {
    const anexo = tramite.anexo_diversidad;
    if (!anexo) return 0;
    const porcentaje = anexo.porcentaje_que_representan || 0;
    if (porcentaje > 10) return 6;
    if (porcentaje >= 6) return 3;
    if (porcentaje >= 5) return 1;
    return 0;
  }

  private calcularPuntosSalarial(tramite: Tramite, totalEmpleosDirectos: number): number {
    const anexo = tramite.anexo_nivel_salarial;
    if (!anexo) return 0;

    const uma = anexo.num_veces_umas || 0;

    if (totalEmpleosDirectos >= 11 && totalEmpleosDirectos <= 50) {
      if (uma > 15) return 5;
      if (uma >= 11) return 4;
      if (uma >= 8) return 3;
      if (uma >= 6) return 2;
      if (uma >= 3) return 1;
    } else if (totalEmpleosDirectos >= 51 && totalEmpleosDirectos <= 250) {
      if (uma > 15) return 10;
      if (uma >= 11) return 8;
      if (uma >= 8) return 6;
      if (uma >= 6) return 4;
      if (uma >= 3) return 2;
    } else if (totalEmpleosDirectos > 250) {
      if (uma > 15) return 15;
      if (uma >= 11) return 12;
      if (uma >= 8) return 9;
      if (uma >= 6) return 6;
      if (uma >= 3) return 3;
    }
    return 0;
  }

  private calcularPuntosInversion(tramite: Tramite): number {
    const total = (tramite.anexos_inversiones || []).reduce((sum, r) => sum + (+(r.cantidad_futura || 0) - +(r.cantidad_actual || 0)), 0);
    // Assuming USD for now or that the value is already in the comparable currency
    if (total > 100000000) return 10;
    if (total > 50000000) return 8;
    if (total > 5000000) return 6;
    if (total > 1000000) return 4;
    if (total > 250000) return 2;
    if (total > 0) return 1;
    return 0;
  }

  private calcularPuntosOrigen(tramite: Tramite): number {
    const anexo = tramite.anexo_origen_inversion;
    if (!anexo) return 0;
    const local = Number(anexo.local_porc) || 0;
    const nacional = Number(anexo.nacional_porc) || 0;
    const extranjera = Number(anexo.extranjera_porc) || 0;

    if (local === 100) return 7;
    if (nacional + local > 50) return 6;
    if (extranjera === 50 && (nacional + local === 50)) return 5;
    if (extranjera > 50 && extranjera < 100) return 4;
    if (extranjera === 100) return 2;
    return 0;
  }

  public calcularPuntosInversionTecnologia(tramite: Tramite, anexo_inversion_tecnologia_total: TramiteAnexoInversionTecnologiaTotal|undefined): number {
    const totalVentas = anexo_inversion_tecnologia_total?.monto || 0;
    if (totalVentas === 0) return 0;

    const montoInversionTec = (tramite.anexos_inversion_tecnologia || []).reduce((acc, curr) => acc + (curr.monto || 0), 0);
    const porcentaje = (montoInversionTec / totalVentas) * 100;

    if (porcentaje >= 10) return 10;
    if (porcentaje >= 7) return 8;
    if (porcentaje >= 5) return 7;
    if (porcentaje >= 2.5) return 5;
    if (porcentaje >= 1) return 3;
    return 0;
  }

  private calcularPuntosProveeduria(tramite: Tramite): number {
    const totalAdquisicion = (tramite.anexos_proveeduria || []).reduce((sum, r) => sum + (Number(r.valor_adquisicion) || 0), 0);
    if (totalAdquisicion === 0) return 0;

    const nacionalAdquisicion = (tramite.anexos_proveeduria || []).reduce((sum, r) => sum + (Number(r.valor_adquisicion) || 0), 0);
    const porcentaje = (nacionalAdquisicion / totalAdquisicion) * 100;

    const esEstatal = tramite.anexo_proveeduria_entidad_federativa?.lugar_adquisicion === 'Baja California';

    if (esEstatal) {
      if (porcentaje > 90) return 8;
      if (porcentaje >= 75 && porcentaje <= 90) return 7;
    }

    if (porcentaje > 51) return 6;
    if (porcentaje >= 26 && porcentaje <= 50) return 5;
    if (porcentaje >= 10 && porcentaje <= 25) return 3;

    return 0;
  }

  private calcularPuntosMercados(tramite: Tramite): number {
    const anexo = tramite.anexo_mercados;
    if (!anexo) return 0;
    const nac = anexo.nacional_porc || 0;
    const ext = anexo.extranjero_porc || 0;

    if (ext > 66) return 6;
    if (nac > 66) return 5;
    if (ext > 33) return 4;
    if (nac > 33) return 3;
    if (nac + ext >= 10) return 2;

    return 0;
  }

  private calcularPuntosPrestaciones(tramite: Tramite): number {
    const anexo = tramite.anexo_prestaciones;
    if (!anexo) return 0;
    let puntos = 0;
    if (anexo.comedor_costo ?? 0 > 0) puntos += 1;
    if (anexo.transporte_costo ?? 0 > 0) puntos += 1;
    if (anexo.guarderia_costo ?? 0 > 0) puntos += 1;
    return puntos;
  }

  private calcularPuntosTecnologiaLimpia(tramite: Tramite): number {
    const anexo = tramite.anexo_tecnologia_limpia;
    if (!anexo) return 0;
    if (anexo.residuos_reciclados_porc && anexo.residuos_reciclados_porc >= 50) return 2;
    return 0;
  }

  private calcularPuntosEnergia(tramite: Tramite): number {
    const anexo = tramite.anexo_fuentes_energia;
    if (!anexo) return 0;
    const ahorro = anexo.consumo_total_de_energia > 0
      ? ((anexo.consumo_total_de_energia - anexo.consumo_posterior) / anexo.consumo_total_de_energia) * 100
      : 0;
    if (ahorro > 60) return 8;
    if (ahorro >= 51) return 6;
    if (ahorro >= 31) return 4;
    if (ahorro >= 21) return 2;
    if (ahorro >= 10) return 1;
    return 0;
  }

  private calcularPuntosCabecera(tramite: Tramite): number {
    const proyecto = tramite.proyecto_inversion;
    if (!proyecto) return 0;
    if (proyecto.fuera_cabecera_municipal) return 15;
    return 0;
  }
}
