import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  ReactiveFormsModule,
  FormBuilder,
  FormGroup,
  Validators,
  AbstractControl,
  FormArray,
} from '@angular/forms';
import { EmpresaService } from '../../../../controllers/empresa.service';
import { Empresa, EmpresaNotificacion } from '../../../../models/empresa';
import { CodigoPostalService, MUNICIPIOS_BC } from '../../../../services/codigo-postal.service';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';

type TipoRegistro = 'MAQUILA' | 'SUBMAQUILA';

@Component({
  selector: 'app-empresa-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './empresa-form.html',
  styleUrl: './empresa-form.css',
})
export class EmpresaForm implements OnInit {
  @Input() empresaId?: number | null;
  @Output() empresaIdChange = new EventEmitter<number>();

  @Output() saved = new EventEmitter<Empresa>();
  @Output() canceled = new EventEmitter<void>();
  @Output() showProyectoInversion = new EventEmitter<void>();

  private localStorageService = inject(LocalStorageService);
  private currentUser = this.localStorageService.getUser()?.user;

  empresaForm: FormGroup = inject(FormBuilder).group({
    nombre_solicitante: [{ value: this.currentUser?.name || '', disabled: true }, [Validators.required, Validators.minLength(3)]],
    actividad_giro: ['', [Validators.required]],
    rfc: [
      { value: this.currentUser?.rfc || '', disabled: true },
      [
        Validators.required,
        Validators.pattern(
          /^[A-Za-z]{3,4}[0-9]{2}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])[A-Za-z0-9]{3}?$/
        ),
      ],
    ],
    escritura_constitutiva: [''],
    escritura_constitutiva_volumen: [''],
    escritura_constitutiva_libro: [''],
    escritura_constitutiva_fecha: [''],
    nombre_notario: [''],
    numero_notario: [''],
    ciudad_notario: [''],
    estado_notario: ['', [Validators.required]],
    tipo_registro: [''],
    otro_tipo_registro: [''],
    codigo_postal: ['', [Validators.required, Validators.pattern(/^[0-9]{5}$/)]],
    calle: ['', [Validators.required]],
    numero_exterior: ['', [Validators.required]],
    numero_interior: [''],
    colonia: ['', [Validators.required]],
    municipio: ['', [Validators.required]],
    telefono: ['', [Validators.pattern(/^[0-9]{10}$/)]],
    pagina_web: [''],
    nombre_representante: ['', [Validators.required, Validators.minLength(3)]],
    escritura_publica: [''],
    escritura_publica_volumen: [''],
    escritura_publica_libro: [''],
    escritura_publica_fecha: [''],
    notario_publico: [''],
    numero_notario_representante: [''],
    ciudad_representante: [''],
    estado_representante: ['', [Validators.required]],
    notificaciones: inject(FormBuilder).array([], [Validators.required, Validators.minLength(1)]),
  });

  get notificaciones(): FormArray {
    return this.empresaForm.get('notificaciones') as FormArray;
  }

  addNotificacion(notificacion?: Partial<EmpresaNotificacion>): void {
    const group = this.fb.group({
      id: [notificacion?.id || null],
      nombre: [notificacion?.nombre || '', [Validators.required, Validators.minLength(3)]],
      correo_electronico: [notificacion?.correo_electronico || '', [Validators.required, Validators.email]],
      telefono: [notificacion?.telefono || '', [Validators.required, Validators.pattern(/^[0-9]{10}$/)]],
    });
    this.notificaciones.push(group);
  }

  removeNotificacion(index: number): void {
    this.notificaciones.removeAt(index);
  }

  isEditMode = false;
  loading = false;
  submitted = false;
  empresa?: Empresa;

  tipoRegistroOptions: { value: TipoRegistro; label: string }[] = [
    { value: 'MAQUILA', label: 'Maquila' },
    { value: 'SUBMAQUILA', label: 'Submaquila' },
  ];

  estadosOptions: string[] = [
    'Aguascalientes',
    'Baja California',
    'Baja California Sur',
    'Campeche',
    'Chiapas',
    'Chihuahua',
    'Ciudad de México',
    'Coahuila',
    'Colima',
    'Durango',
    'Estado de México',
    'Guanajuato',
    'Guerrero',
    'Hidalgo',
    'Jalisco',
    'Michoacán',
    'Morelos',
    'Nayarit',
    'Nuevo León',
    'Oaxaca',
    'Puebla',
    'Querétaro',
    'Quintana Roo',
    'San Luis Potosí',
    'Sinaloa',
    'Sonora',
    'Tabasco',
    'Tamaulipas',
    'Tlaxcala',
    'Veracruz',
    'Yucatán',
    'Zacatecas',
  ];

  municipiosOptions = MUNICIPIOS_BC;

  private fb = inject(FormBuilder);
  private empresaService = inject(EmpresaService);
  private codigoPostalService = inject(CodigoPostalService);

  async ngOnInit(): Promise<void> {
    const empresaId = this.empresaId

    this.isEditMode = !!empresaId

    await this.codigoPostalService.cargarCodigosPostales();

    this.empresaForm.get('codigo_postal')?.valueChanges.subscribe(() => {
      this.validarCodigoPostalConMunicipio();
    });

    this.empresaForm.get('municipio')?.valueChanges.subscribe(() => {
      this.validarCodigoPostalConMunicipio();
    });

    if (this.isEditMode && empresaId) {
      await this.loadEmpresaData(empresaId);
    } else {
      this.addNotificacion();
    }
  }

  private async loadEmpresaData(empresaId: number): Promise<void> {
    if (!empresaId) return;

    this.loading = true;
    this.empresa = await this.empresaService.find(empresaId, { relations: ['notificaciones'] });

    if (this.empresa) {
      this.empresaForm.patchValue(this.empresa);
      
      this.notificaciones.clear();
      if (this.empresa.notificaciones && this.empresa.notificaciones.length > 0) {
        this.empresa.notificaciones.forEach(notif => this.addNotificacion(notif));
      } else {
        this.addNotificacion();
      }
    }
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.empresaForm.controls;
  }

  validarCodigoPostalConMunicipio(): void {
    const codigoPostal = this.empresaForm.get('codigo_postal')?.value;
    const municipio = this.empresaForm.get('municipio')?.value;
    const codigoPostalControl = this.empresaForm.get('codigo_postal');

    if (codigoPostal && municipio && codigoPostalControl) {
      const valido = this.codigoPostalService.validarCodigoPostalParaMunicipio(codigoPostal, municipio);

      if (valido) {
        codigoPostalControl.setErrors(null);
      } else {
        codigoPostalControl.setErrors({ municipioInvalido: true });
      }
    }
  }

  async onSubmit(showSuccessAlert = true): Promise<void> {
    if (this.empresaForm.invalid) {
      this.empresaForm.markAllAsTouched();
      return;
    }

    const formData = { ...this.empresaForm.getRawValue() };

    if (this.isEditMode && this.empresa) {
      await this.empresaService.update(this.empresa.id, formData, false);
      this.empresa ={
        ...this.empresa,
        ...formData
      }
    } else {
      this.empresa =await this.empresaService.new(formData, false);
    }
    
    this.saved.emit(this.empresa);
    if (showSuccessAlert) {
      this.submitted = true;
      this.showProyectoInversion.emit();
      setTimeout(() => this.submitted = false, 5000);
    }
  }

  async onButtonClick(): Promise<void> {
    await this.onSubmit(true);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar Empresa' : 'Nueva Empresa';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar Empresa' : 'Guardar Empresa';
  }
}
