import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { debounceTime, distinctUntilChanged } from 'rxjs';
import { TramiteAnexoFuentesEnergiaRenovableService } from '../../../../controllers/tramite-anexo-fuentes-energia-renovable.service';
import { TramiteAnexoFuentesEnergiaRenovable } from '../../../../models/tramite-anexo-fuentes-energia-renovable';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-fuentes-energias-renovables-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-fuentes-energias-renovables-form.html',
  styleUrl: './tramite-anexo-fuentes-energias-renovables-form.css',
})
export class TramiteAnexoFuentesEnergiasRenovablesForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoFuentesEnergiaRenovable?: TramiteAnexoFuentesEnergiaRenovable;
  @Output() tramiteAnexoFuentesEnergiaRenovableChange = new EventEmitter<TramiteAnexoFuentesEnergiaRenovable>();
  @Output() saved = new EventEmitter<TramiteAnexoFuentesEnergiaRenovable>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    consumo_total_de_energia: [null, [Validators.required, Validators.min(0)]],
    consumo_posterior: [null, [Validators.required, Validators.min(0)]],
    unidad_medida: ['', Validators.required],
    unidad_medida_otra: [''],
    fuente_energia_implementada: ['', Validators.required],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  unidadMedidaOptions = [
    'J',
    'MJ',
    'GJ',
    'Wh',
    'kWh',
    'MWh',
    'Otro'
  ];

  private fb = inject(FormBuilder);
  private tramiteAnexoFuentesEnergiaRenovableService = inject(TramiteAnexoFuentesEnergiaRenovableService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoFuentesEnergia']);
      this.tramiteAnexoFuentesEnergiaRenovable = tramite?.anexo_fuentes_energia;
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoFuentesEnergiaRenovable?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoFuentesEnergiaRenovable) {
      await this.loadData();
    }

    this.form.valueChanges.pipe(
      debounceTime(3000),
      distinctUntilChanged()
    ).subscribe(() => {
      this.onSubmit();
    });
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoFuentesEnergiaRenovable) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoFuentesEnergiaRenovable);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  onConsumoChange(event: Event, controlName: string): void {
    const target = event.target as HTMLInputElement;
    const valor = target.value ? parseFloat(target.value.replace(/,/g, '')) : 0;
    this.form.get(controlName)?.setValue(valor);
  }

  get showOtraUnidad(): boolean {
    return this.form.get('unidad_medida')?.value === 'Otro';
  }

  get porcentajeAhorro(): number | null {
    const consumoTotal = this.form.get('consumo_total_de_energia')?.value;
    const consumoPosterior = this.form.get('consumo_posterior')?.value;

    if (!consumoTotal || !consumoPosterior || consumoTotal <= 0) {
      return null;
    }

    return ((consumoTotal - consumoPosterior) / consumoTotal) * 100;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = { ...this.form.value };

    if (formData.unidad_medida === 'Otro') {
      formData.unidad_medida = formData.unidad_medida_otra || 'Otro';
    }

    delete formData.unidad_medida_otra;

    let result: TramiteAnexoFuentesEnergiaRenovable | undefined;

    if (this.isEditMode && this.tramiteAnexoFuentesEnergiaRenovable) {
      await this.tramiteAnexoFuentesEnergiaRenovableService.update(this.tramiteAnexoFuentesEnergiaRenovable.id, formData);
      result = {
        ...this.tramiteAnexoFuentesEnergiaRenovable,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoFuentesEnergiaRenovableService.new(formData);
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoFuentesEnergiaRenovableChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      consumo_total_de_energia: null,
      consumo_posterior: null,
      unidad_medida: '',
      unidad_medida_otra: '',
      fuente_energia_implementada: '',
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Registrar';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
