  private http = inject(HttpClient);
  private utils = inject(UtilsService);
  private tramiteService = inject(TramiteService);
  private puntosService = inject(PuntosAnexoService);

  private cachedLogoSeiBase64: string | null = null;
  private cachedLogoBcBase64: string | null = null;
  private cachedWatermarkBase64: string | null = null;
  private cachedFooterSei: string | null = null;
  private documentData: DocumentData | null = null;

  /**
   * Carga una imagen desde assets y la convierte a base64 data URL
   */
  private async loadImageAsBase64(imagePath: string): Promise<string> {
    try {
      const blob = await firstValueFrom(
        this.http.get(imagePath, { responseType: 'blob' })
      );

      return new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === 'string') {
            resolve(reader.result);
          } else {
            reject(new Error('Error converting image to base64'));
          }
        };
        reader.onerror = () => reject(new Error('FileReader error'));
        reader.readAsDataURL(blob);
      });
    } catch (error) {
      console.error('Failed to load image:', error);
      throw new Error(`Failed to load image from ${imagePath}: ${error}`);
    }
  }

  private async loadImages() {
    if (!this.cachedLogoSeiBase64) {
      this.cachedLogoSeiBase64 = await this.loadImageAsBase64('assets/logo_sei.png');
    }
    if (!this.cachedLogoBcBase64) {
      this.cachedLogoBcBase64 = await this.loadImageAsBase64('assets/logo_baja_california.png');
    }
    if (!this.cachedWatermarkBase64) {
      this.cachedWatermarkBase64 = await this.loadImageAsBase64('assets/marca_agua_sei.png');
    }
    if (!this.cachedFooterSei) {
      this.cachedFooterSei = await this.loadImageAsBase64('assets/footer_sei.png')
    }

  }

  /**
   * Genera el header con los logos y el texto
   */
